//! 🧬️ SemioTextMutation — document mutation dispatch. Semantic vocabulary derived from
//! `📸️snapshot/🦀️.rs`'s `SemioTextSnapshot` shape (one index-keyed, id-less ordered
//! collection — `runs`, each carrying its own nested `marks` collection) per
//! `../SEMANTIC-MUTATIONS-OVERHAUL/📓️taxonomy.md`/`📓️fanout-brief.md`. `impl protocol::Mutation`/
//! `SemanticMutation` below are generated by `#[derive(dsl::Mutations)]` — never hand-written.
//!
//! `runs: Vec<SemioTextRun>` has no stable id (addressing rule #3): `insert-run`/`remove-run`
//! address by index (inserted = FINAL-state, removed = BASE-state), `reorder-runs` moves one run
//! within the sequence, `edit-run` replaces one run's authored `content` body, `change-run-
//! language` sets one run's BCP-47 tag. `marks: Vec<SemioTextMark>` (nested inside each run) is
//! itself an id-less ordered collection, addressed the same way one level deeper: `add-mark`/
//! `remove-mark` take `{run_index, index}`, `add`/`remove` per the core verb table's "attach/detach
//! a set-like member" entry.
//!
//! Every triad leaf is mounted directly as a `mutations`-sibling module in `🦀️.rs` (the stdio
//! W2 agent owns `🦀️.rs`, so no self-wiring `#[path = "."]` blocks are needed here).

use crate::artifacts::semio::standards::v1::subsets::text::schema::diff::SemioTextDiff;
use crate::artifacts::semio::standards::v1::subsets::text::schema::snapshot::SemioTextSnapshot;

//#region 🔖️Leaves
use super::add_mark;
use super::change_run_language;
use super::edit_run;
use super::insert_run;
use super::remove_mark;
use super::remove_run;
use super::reorder_runs;
//#endregion 🔖️Leaves

//#region 🔖️Mutations
/// 🧬️ Every variant wraps exactly one `protocol::MutationKind<SemioTextSnapshot, SemioTextMutation>`
/// payload struct declared in the corresponding triad leaf's `🦠️mutation/🦀️.rs`. This
/// plugin crate reaches the derive through the `dsl` extern-crate alias `🦀️.rs` declares
/// (`extern crate semio_framework_os_kernel as dsl;`), the same spelling every other stdio subset's
/// eventual `dsl::Mutations` derive uses (confirmed against `din4108`'s already-compiling facet,
/// this ticket's binding reference).
#[derive(Clone, Debug, PartialEq, value_derive::ToValue, value_derive::FromValue, dsl::Mutations)]
#[mutations(snapshot = SemioTextSnapshot, diff = SemioTextDiff, schema = "s.stdio.semio.text")]
pub enum SemioTextMutation {
    InsertRun(insert_run::InsertRun),
    RemoveRun(remove_run::RemoveRun),
    EditRun(edit_run::EditRun),
    ChangeRunLanguage(change_run_language::ChangeRunLanguage),
    ReorderRuns(reorder_runs::ReorderRuns),
    AddMark(add_mark::AddMark),
    RemoveMark(remove_mark::RemoveMark),
}

/// 🏷️ Kebab-case spelling of every `SemioTextMutation` variant, in declaration order — the
/// vocabulary the `semio-v1-text` mutation catalog (`../../🔣️oracle.json`) declares and
/// `mutate-semio-text`'s exhaustive test case measures itself against. `kinds_match_the_enum_and_
/// the_catalog` below is what keeps this list honest against the enum, since the framework never
/// parses Rust.
pub const KINDS: &[&str] = &["insert-run", "remove-run", "edit-run", "change-run-language", "reorder-runs", "add-mark", "remove-mark"];
//#endregion 🔖️Mutations

//#region 🔖️Apply
/// ▶️ Applies a mutation to `snapshot` in place, returning the diff — kept from the pre-wave facet
/// (consumed by `../🦀️.rs`'s `SemioTextBuilderConstruction::mutate`).
// 🚫️async: E1 pure codec/computation helper (file verified I/O-free, consumed via Fn-bound combinator/Display) — see R9
pub fn apply_semio_text_mutation(snapshot: &mut SemioTextSnapshot, mutation: &SemioTextMutation) -> protocol::MutationOutcome<SemioTextDiff> {
    use protocol::Mutation;
    let outcome = <SemioTextMutation as Mutation<SemioTextSnapshot>>::diff(mutation, snapshot);
    outcome.apply_to(snapshot)
}

/// ↩️ Computes `mutation`'s own inverse against `base` — a thin wrapper around
/// `protocol::Mutation::inverse` so external Rust callers that cannot name this crate's private
/// `protocol` extern-crate item (the `mutate-semio-text` test adapter, whose `inverse-<kind>`
/// scenarios need a mutation's own computed inverse) can still reach the inverse law that
/// [`apply_semio_text_mutation`] alone cannot. Same shape as `✳️kit`'s `inverse_semio_kit_mutation`.
// 🚫️async: E1 pure codec/computation helper (file verified I/O-free, consumed via Fn-bound combinator/Display) — see R9
pub fn inverse_semio_text_mutation(mutation: &SemioTextMutation, base: &SemioTextSnapshot) -> Vec<SemioTextMutation> {
    use protocol::Mutation;
    <SemioTextMutation as Mutation<SemioTextSnapshot>>::inverse(mutation, base)
}

/// 📥️ Decodes this facet's own externally-tagged (`{"<VariantName>": {<snake_case payload>}}`) JSON
/// projection — no `#[value(rename_all)]` sits on this enum or its payload structs, which is
/// exactly the shape the committed `<kind>/🧪️tests/<fixture>/🦠️mutation/🔣️.json` vectors
/// carry — into a real [`SemioTextMutation`]. Same rationale as
/// `../📸️snapshot/🦀️.rs`'s `decode_semio_text_snapshot_json`.
// 🚫️async: E1 pure codec/computation helper (file verified I/O-free, consumed via Fn-bound combinator/Display) — see R9
pub fn decode_semio_text_mutation_json(text: &str) -> Result<SemioTextMutation, String> {
    pack::from_json_str(text).map_err(|error| error.to_string())
}
//#endregion 🔖️Apply

//#region 🧪️Tests
#[cfg(test)]
mod tests {
    use super::*;
    use crate::artifacts::semio::standards::v1::subsets::text::schema::snapshot::{SemioTextMark, SemioTextMarkKind, SemioTextRun};
    use protocol::{Mutation, MutationDiff, SemanticMutation};

    // 🚫️async: E1 pure inherent-impl helper (file verified I/O-free, consumed via opaque-type-hostile call site) — see R9
    fn fixture() -> SemioTextSnapshot {
        SemioTextSnapshot {
            runs: vec![
                SemioTextRun { language: "en".into(), content: "hello".into(), marks: vec![] },
                SemioTextRun { language: "en".into(), content: "world".into(), marks: vec![SemioTextMark { kind: SemioTextMarkKind::Bold, href: String::new() }] },
            ],
            ..Default::default()
        }
    }

    // 🚫️async: E1 pure inherent-impl helper (file verified I/O-free, consumed via opaque-type-hostile call site) — see R9
    fn round_trip(base: &SemioTextSnapshot, operation: &SemioTextMutation) -> SemioTextSnapshot {
        let forward = operation.diff(base).diff().apply(base).expect("apply must succeed for a well-formed fixture");
        let backwards = operation.inverse(base);
        let mut restored = forward.clone();
        // 🔧️ Each inverse's diff must be computed against the CURRENT (`restored`) state, not the
        // stale pre-operation `base` — `text`'s whole-list-replace diff shape (📓️taxonomy.md's
        // `SemioTextRunList` wrapper) reconstructs the entire `runs` vec from whatever base it is
        // given, so calling it against the wrong base silently discards the forward mutation's
        // effect instead of undoing it. Same standard `mutation.diff(&current); current =
        // diff.diff().apply(&current)` threading `apply_semio_image_mutation`/`apply_semio_mutation`
        // establish elsewhere in this standard.
        for back in &backwards {
            restored = back.diff(&restored).diff().apply(&restored).expect("apply must succeed for a well-formed fixture");
        }
        assert_eq!(&restored, base, "inverse must exactly restore the pre-operation fixture");
        forward
    }

    #[semio_framework_async_macros::async_test]
    async fn insert_remove_run_round_trips() {
        let base = fixture();
        let new_run = SemioTextRun { language: "de".into(), content: "hallo".into(), marks: vec![] };

        let insert = SemioTextMutation::InsertRun(insert_run::InsertRun { index: 1, run: new_run.clone() });
        let after_insert = round_trip(&base, &insert);
        assert_eq!(after_insert.runs.len(), base.runs.len() + 1);
        assert_eq!(after_insert.runs[1], new_run);

        let undo = insert.inverse(&base);
        assert_eq!(undo, vec![SemioTextMutation::RemoveRun(remove_run::RemoveRun { index: 1 })]);

        let remove = SemioTextMutation::RemoveRun(remove_run::RemoveRun { index: 0 });
        let after_remove = round_trip(&base, &remove);
        assert_eq!(after_remove.runs.len(), base.runs.len() - 1);
        assert_eq!(after_remove.runs[0], base.runs[1]);
    }

    #[semio_framework_async_macros::async_test]
    async fn remove_run_of_an_out_of_range_index_has_an_empty_inverse() {
        let base = fixture();
        let remove = SemioTextMutation::RemoveRun(remove_run::RemoveRun { index: 99 });
        assert!(remove.inverse(&base).is_empty(), "removing an absent index has nothing to undo");
        assert_eq!(remove.diff(&base).diff().apply(&base).expect("apply must succeed for a well-formed fixture"), base, "an out-of-range remove is a no-op");
    }

    #[semio_framework_async_macros::async_test]
    async fn edit_run_and_change_run_language_round_trip() {
        let base = fixture();

        let edit = SemioTextMutation::EditRun(edit_run::EditRun { index: 0, new_content: "greetings".into() });
        let after = round_trip(&base, &edit);
        assert_eq!(after.runs[0].content, "greetings");
        assert_eq!(after.runs[0].language, base.runs[0].language);

        let change_lang = SemioTextMutation::ChangeRunLanguage(change_run_language::ChangeRunLanguage { index: 0, new_language: "fr".into() });
        let after = round_trip(&base, &change_lang);
        assert_eq!(after.runs[0].language, "fr");

        let missing = SemioTextMutation::EditRun(edit_run::EditRun { index: 99, new_content: "x".into() });
        assert!(missing.inverse(&base).is_empty(), "editing an absent index has nothing to undo");
    }

    #[semio_framework_async_macros::async_test]
    async fn reorder_runs_round_trips() {
        let base = fixture();
        assert!(base.runs.len() >= 2, "fixture must have at least two runs to exercise reorder");

        let reorder = SemioTextMutation::ReorderRuns(reorder_runs::ReorderRuns { from: 0, to: 1 });
        let after = round_trip(&base, &reorder);
        assert_eq!(after.runs[0], base.runs[1]);
        assert_eq!(after.runs[1], base.runs[0]);
    }

    #[semio_framework_async_macros::async_test]
    async fn add_remove_mark_round_trips() {
        let base = fixture();
        let mark = SemioTextMark { kind: SemioTextMarkKind::Link, href: "https://semio.tech".into() };

        let add = SemioTextMutation::AddMark(add_mark::AddMark { run_index: 0, index: 0, mark: mark.clone() });
        let after_add = round_trip(&base, &add);
        assert_eq!(after_add.runs[0].marks, vec![mark.clone()]);

        let undo = add.inverse(&base);
        assert_eq!(undo, vec![SemioTextMutation::RemoveMark(remove_mark::RemoveMark { run_index: 0, index: 0 })]);

        let remove = SemioTextMutation::RemoveMark(remove_mark::RemoveMark { run_index: 1, index: 0 });
        let after_remove = round_trip(&base, &remove);
        assert!(after_remove.runs[1].marks.is_empty());
    }

    #[semio_framework_async_macros::async_test]
    async fn add_remove_mark_of_an_absent_run_has_an_empty_inverse() {
        let base = fixture();
        let remove = SemioTextMutation::RemoveMark(remove_mark::RemoveMark { run_index: 99, index: 0 });
        assert!(remove.inverse(&base).is_empty());
        assert_eq!(remove.diff(&base).diff().apply(&base).expect("apply must succeed for a well-formed fixture"), base);
    }

    #[semio_framework_async_macros::async_test]
    async fn semantic_kinds_cover_every_variant() {
        assert_eq!(SemioTextMutation::kinds().len(), 7);
        let mutation = SemioTextMutation::RemoveRun(remove_run::RemoveRun { index: 2 });
        assert_eq!(mutation.semantics().kind, "remove-run");
        assert_eq!(mutation.semantics().record, "RemovedRun");
        assert_eq!(mutation.target(), vec!["2".to_string()]);
    }

    /// 🏷️ `KINDS` (this facet's own const, consumed by `mutate-semio-text`'s adapter) must name
    /// every declared variant, in the exact order and spelling `#[derive(dsl::Mutations)]` assigns —
    /// the framework never parses Rust, so this is what keeps the catalog honest.
    #[semio_framework_async_macros::async_test]
    async fn kinds_match_the_enum_and_the_catalog() {
        let descriptors = SemioTextMutation::kinds();
        assert_eq!(KINDS.len(), descriptors.len(), "KINDS must name exactly one entry per declared variant");
        for (kind, descriptor) in KINDS.iter().zip(descriptors.iter()) {
            assert_eq!(*kind, descriptor.kind, "KINDS must match #[derive(dsl::Mutations)]'s own declaration order and spelling");
        }
        let manifest = include_str!("../../🔣️oracle.json");
        for kind in KINDS {
            assert!(manifest.contains(&format!("\"{kind}\"")), "KINDS entry {kind:?} must also appear in the committed oracle manifest's catalog");
        }
    }
}
//#endregion 🧪️Tests

